package com.tiviloom.mobile.test;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.Rect;import org.json.*;import java.lang.reflect.*;
/** Patch integration acceptance using local media, real layouts and OS notifications. */
public final class PatchPlayerTest extends NativePlayerTest {
 View findType(View root,Class<?> type){if(type.isInstance(root))return root;if(root instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)root;for(int i=0;i<group.getChildCount();i++){View result=findType(group.getChildAt(i),type);if(result!=null)return result;}}return null;}
 void invoke(String method,String value)throws Exception{onMain(()->{host().getClass().getMethod(method,String.class).invoke(host(),value);return true;});}
 void dismiss()throws Exception{onMain(()->{Dialog d=(Dialog)field("activeDialog");if(d!=null)d.dismiss();return true;});}
 Object activeDecoder()throws Exception{Object nativePlayer=field("player");return nativePlayer!=null?nativePlayer:field("compatibility");}
 Object compatibilityCall(String name)throws Exception{Object compat=field("compatibility");Method method=compat.getClass().getDeclaredMethod(name);method.setAccessible(true);return method.invoke(compat);}
 Object compatibilityMediaPlayer()throws Exception{Object compat=field("compatibility");Field mp=compat.getClass().getDeclaredField("mp");mp.setAccessible(true);return mp.get(compat);}
 @Override public void onStart(){try{
  Intent intent=new Intent().setClassName("com.tiviloom.mobile","com.tiviloom.mobile.NativePlaybackActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);intent.putExtra("payload",new JSONObject().put("url","http://127.0.0.1:18888/demo.mp4").put("name","AZTV").put("id","az-hd").put("fullscreen",true).toString());activity=startActivitySync(intent);onMain(()->{Class.forName("androidx.media3.common.Player",true,activity.getClassLoader()).getMethod("setRepeatMode",int.class).invoke(field("player"),1);return true;});
  check("decoded video and audio output become ready",()->{waitFor(()->{if(field("compatibility")!=null)return (boolean)compatibilityCall("frame")&&(boolean)compatibilityCall("audioDecoded");return renderedVideo()>0&&playing()&&(!(boolean)field("expectsAudio")||(boolean)field("audioRendered"));});});Object decoder=activeDecoder();require(decoder!=null,"No active decoder");
  check("search folds Azerbaijani dotted I, e and accents",()->{Method method=host().getClass().getDeclaredMethod("searchKey",String.class);method.setAccessible(true);require("ictimai seki".equals(method.invoke(null,"İCTİMAİ ŞƏKİ")),"Search normalization differs");});
  check("same-name channels highlight only matching ID",()->{JSONArray list=new JSONArray().put(new JSONObject().put("id","az-hd").put("name","AZTV").put("group","AZ")).put(new JSONObject().put("id","az-sd").put("name","AZTV").put("group","AZ")).put(new JSONObject().put("id","ictimai").put("name","İctimai").put("group","Azərbaycan"));invoke("catalogue",new JSONObject().put("catalogue",list).put("history",new JSONArray()).put("activeId","az-hd").put("mode","channels").toString());waitFor(()->(boolean)field("dialogOpen"));onMain(()->{Dialog d=(Dialog)field("activeDialog");ListView view=(ListView)findType(d.getWindow().getDecorView(),ListView.class);require(view.getAdapter().getCount()==3,"Missing catalogue rows");require(view.getAdapter().getView(0,null,view).isSelected(),"HD not active");require(!view.getAdapter().getView(1,null,view).isSelected(),"SD falsely active");return true;});});
  check("debounced native query returns final Azerbaijani result",()->{onMain(()->{Dialog d=(Dialog)field("activeDialog");EditText input=(EditText)findType(d.getWindow().getDecorView(),EditText.class);input.setText("zz");input.setText("ictimai");return true;});waitFor(()->{Dialog d=(Dialog)field("activeDialog");ListView list=(ListView)findType(d.getWindow().getDecorView(),ListView.class);return list.getAdapter().getCount()==1;});dismiss();require(activeDecoder()==decoder,"Search replaced decoder");});
  check("cancelled catalogue work cannot reopen a dialog",()->{JSONObject data=new JSONObject().put("mode","channels").put("catalogue",new JSONArray()).put("history",new JSONArray());onMain(()->{host().getClass().getMethod("catalogue",String.class).invoke(host(),data.toString());host().getClass().getMethod("back").invoke(host());return true;});SystemClock.sleep(250);require(!(boolean)field("dialogOpen"),"Cancelled catalogue reopened");});
  check("preferences change mute and fit without replacing decoder",()->{invoke("preferences","{\"motion\":false,\"muted\":true,\"fit\":\"cover\"}");onMain(()->{Object value=field("player")!=null?playerCall("getVolume"):compatibilityMediaPlayer().getClass().getMethod("getVolume").invoke(compatibilityMediaPlayer());require(((Number)value).floatValue()==0f,"Mute did not apply");return true;});require(activeDecoder()==decoder,"Prefs replaced decoder");invoke("preferences","{\"motion\":true,\"muted\":false,\"fit\":\"contain\"}");});
  check("interrupting a control fade restores clickability",()->{onMain(()->{View controls=(View)field("controls");Class<?> motion=Class.forName("com.tiviloom.mobile.UiMotion",true,activity.getClassLoader());Method visibility=motion.getDeclaredMethod("visibility",View.class,boolean.class);visibility.setAccessible(true);visibility.invoke(null,controls,false);visibility.invoke(null,controls,true);return true;});SystemClock.sleep(250);onMain(()->{View controls=(View)field("controls");require(controls.isClickable()&&controls.getVisibility()==View.VISIBLE&&controls.getAlpha()>.99f,"Interrupted fade left controls disabled");return true;});});
  check("More to audio preserves the new native dialog",()->{tapLabel("Digər funksiyalar");waitFor(()->(boolean)field("dialogOpen"));Dialog old=(Dialog)field("activeDialog");View choice=findLabel(old.getWindow().getDecorView(),"Səs dili");require(choice!=null,"Audio choice missing");onMain(()->{choice.performClick();return true;});SystemClock.sleep(300);onMain(()->{Dialog current=(Dialog)field("activeDialog");require(current!=null&&current!=old&&current.isShowing()&&(boolean)field("dialogOpen"),"Old dismissal cleared new dialog state");return true;});dismiss();});
  check("narrow fullscreen moves secondary controls into More",()->{onMain(()->{View root=(View)field("root");android.view.ViewGroup.LayoutParams bounds=root.getLayoutParams();bounds.width=Math.round(360*activity.getResources().getDisplayMetrics().density);root.setLayoutParams(bounds);return true;});SystemClock.sleep(350);onMain(()->{LinearLayout tools=(LinearLayout)field("toolsRow");int hidden=0;for(int i=0;i<tools.getChildCount();i++){View v=tools.getChildAt(i);if("secondary".equals(v.getTag())&&v.getVisibility()==View.GONE)hidden++;}require(hidden==3,"Secondary controls not collapsed");View root=(View)field("root");Rect screen=new Rect();root.getGlobalVisibleRect(screen);inspect(root,screen,activity.getResources().getDisplayMetrics().density);return true;});capture("patch-narrow");});
  check("notification schedule survives receiver and cancel removes saved alarm",()->{ClassLoader loader=activity.getClassLoader();Class<?> scheduler=Class.forName("com.tiviloom.mobile.ReminderScheduler",true,loader);Method schedule=scheduler.getDeclaredMethod("schedule",Context.class,String.class,String.class,long.class);schedule.setAccessible(true);android.content.SharedPreferences prefs=activity.getSharedPreferences("reminders",0);prefs.edit().putBoolean("enabled",true).commit();schedule.invoke(null,activity,"patch-reminder","Patch programme",System.currentTimeMillis()+120000);require(prefs.contains("patch-reminder"),"Alarm not stored");Intent broadcast=new Intent().setClassName("com.tiviloom.mobile","com.tiviloom.mobile.ReminderReceiver").putExtra("key","patch-reminder").putExtra("title","Patch programme");activity.sendBroadcast(broadcast);waitFor(()->!prefs.contains("patch-reminder"));NotificationManager manager=(NotificationManager)activity.getSystemService(Context.NOTIFICATION_SERVICE);waitFor(()->manager.getActiveNotifications().length>0);manager.cancel("patch-reminder",0);Method cancel=scheduler.getDeclaredMethod("cancelAll",Context.class);cancel.setAccessible(true);cancel.invoke(null,activity);prefs.edit().putBoolean("enabled",false).apply();});
 }catch(Throwable e){failed++;report.append("FATAL ").append(e.toString());}finally{if(activity!=null)runOnMainSync(()->activity.finish());}Bundle result=new Bundle();result.putString("stream",report+"\nPASSED="+passed+" FAILED="+failed+"\n");finish(failed==0?-1:0,result);}
}
